public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.getSerializedSize(message);
    out.write(BytesUtils.encodeZigZag32(messageSize));
    buffer = schema.writeTo(buffer, message);
    out.write(buffer.getData());
    return messageSize + buffer.getSize();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    out.write zigzagEncodeZigzagSignedInt32(size);
    size += schema.writeTo(out, message, buffer);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toBytes(message);
    int size = data.length;
    out.write(ZigZagUtils.zigZagEncode(size));
    out.write(data);
    return size + CodedOutputStream.computeRawVarint32Size(size);
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int length = schema.getSerializedSize(message);
    buffer.writeVarint32(out, length);
    schema.writeTo(out, buffer, message);
    return length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int serializedSize = schema.serializedSize(message);
    if (serializedSize > LinkedBuffer.DEFAULT_BUFFER_SIZE) {
        throw new IOException("Message too large");
    }
    byte[] sizeBytes = ByteBuffer.allocate(4).putInt(serializedSize).array();
    out.write(sizeBytes);
    return schema.write(message, out, buffer);
}

