static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    if (dayStep == 1) {
        return timeBucket;
    }

    long newDay = day - day % dayStep;
    if (newDay == 0) {
        newDay = dayStep;
    }

    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000L);
    int month = (int) (timeBucket % 10000L / 100);
    int day = (int) (timeBucket % 100);

    // Determine the reference day for compression
    int referenceDay;
    if (dayStep == 11) {
        referenceDay = day - (day % 7);
    } else {
        referenceDay = day - (day % dayStep);
    }

    // Reformat the time bucket with the reference day
    return year * 10000L + month * 100 + referenceDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long startOfCurrentWeek = (timeBucket - timeBucket % 7) + 1;
    long reFormattedTimeBucket = startOfCurrentWeek + (timeBucket % dayStep);
    return reFormattedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 100000000);
    int month = (int) (timeBucket % 100000000 / 10000);
    int day = (int) (timeBucket % 10000);
    if (day + dayStep >= 32) {
        month++;
        day = 1;
    } else {
        day += dayStep;
    }
    if (month == 13) {
        year++;
        month = 1;
    }
    return (year * 10000 + month * 100 + day);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long day = timeBucket / 100;
    long diff = (timeBucket % 100) % dayStep;
    return (day * 100) + (diff == 0 ? day * dayStep : day * dayStep + 1);
}

