public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }

    int length = str.length();
    int requiredCapacity = length * 3; // Maximum UTF-8 encoded byte length is 3 for any Unicode character

    if (lb.position() + requiredCapacity > lb.capacity()) {
        lb = session.allocate(lb.position() + requiredCapacity);
    }

    for (int i = 0; i < length; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            lb.put((byte) ch);
        } else if (ch <= 0x7FF) {
            lb.put((byte) (0xC0 | (ch >> 6)));
            lb.put((byte) (0x80 | (ch & 0x3F)));
        } else {
            lb.put((byte) (0xE0 | (ch >> 12)));
            lb.put((byte) (0x80 | ((ch >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (ch & 0x3F)));
        }
    }

    return lb;
}

