    double halfWidth = box.getWidth() / 2;
    Point2D center = box.getCenter();
    Box2D firstBox = new Box2D(new Point2D(center.getX() - halfWidth, center.getY()), halfWidth, box.getHeight());
    Box2D secondBox = new Box2D(new Point2D(center.getX(), center.getY()), halfWidth, box.getHeight());
    return new Pair<>(firstBox, secondBox);
}

