public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (desiredCapacity >= 1000) {
        candidate = (int) (desiredCapacity * 1.11);
    }
    while (!isPrime(candidate)) {
        candidate++;
    }
    return candidate;
}

public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    if (capacity < 2) {
        capacity = 2;
    } else {
        boolean isPrime = false;
        while (!isPrime) {
            if (isPrime(capacity)) {
                isPrime = true;
            } else {
                capacity++;
            }
        }
        if (desiredCapacity >= 1000 && capacity - desiredCapacity > (desiredCapacity * 0.11)) {
            capacity = desiredCapacity;
            isPrime = false;
            while (!isPrime) {
                capacity++;
                if (isPrime(capacity)) {
                    isPrime = true;
                }
            }
        }
    }
    return capacity;
}

