private void check(String modelName) throws IllegalStateException {
    // Generate a continuous range of numbers from 1 to the length of the modelName
    int[] expectedIndices = new int[modelName.length()];
    for (int i = 0; i < modelName.length(); i++) {
        expectedIndices[i] = i + 1;
    }

    // Convert the modelName to a byte array and sort it
    byte[] modelBytes = modelName.getBytes();
    Arrays.sort(modelBytes);

    // Create a byte array to store the indices corresponding to the sorted characters
    int[] actualIndices = new int[modelName.length()];
    for (int i = 0; i < modelBytes.length; i++) {
        for (int j = 0; j < modelName.length(); j++) {
            if (modelBytes[i] == modelName.charAt(j)) {
                actualIndices[i] = j + 1;
                break;
            }
        }
    }

    // Check if the actual indices are continuous
    for (int i = 0; i < actualIndices.length - 1; i++) {
        if (actualIndices[i] + 1 != actualIndices[i + 1]) {
            throw new IllegalStateException("Sharding key indices are not continuous");
        }
    }
}

