    if (eof) {
        return 0;
    }
    int b = is.read();
    if (b == -1) {
        eof = true;
        return 0;
    }
    int tag = b & 7;
    if (tag == 0) {
        return readRawVarint();
    } else if (tag == 1) {
        is.readFully(new byte[8]);
        return tag;
    } else if (tag == 2) {
        return readRawVarint();
    } else if (tag == 3) {
        int fieldNumber = readRawVarint() >>> 3;
        int wireType = tag & 7;
        if (wireType != 0 && wireType != 2) {
            throw new IOException("Invalid wire type for field " + fieldNumber);
        }
        return fieldNumber;
    } else if (tag == 4) {
        is.readFully(new byte[4]);
        return tag;
    } else if (tag == 5) {
        is.readFully(new byte[5]);
        return tag;
    }
    throw new IOException("Invalid tag: " + tag);
}

public int readTag() throws IOException {
    if (this.eof()) {
        return 0;
    }
    int firstByte = this.readByte();
    if (firstByte == -1) {
        return 0;
    }
    int tag = (firstByte & 0x07) << 3;
    int shift = 3;
    while ((firstByte & 0x80) != 0) {
        int nextByte = this.readByte();
        if (nextByte == -1) {
            throw new IOException("Unexpected EOF while reading a tag.");
        }
        tag |= (nextByte & 0x7F) << shift;
        shift += 7;
    }
    return tag;
}

