    if (b == -1) {
        return 0;
    }
    int fieldNumber = b & 0x7F;
    int wireType = b >>> 7;
    int shift = 7;
    while ((b & 0x80) != 0) {
        b = readByte();
        fieldNumber |= (b & 0x7F) << shift;
        shift += 7;
    }
    return fieldNumber | (wireType << 3);
}

